const HARTHMERE_BUSINESS_FURNITURE_ITEM_ID_BY_NATIVE_ID = new Map<
  number,
  string
>();
for (const [itemId, nativeId] of Object.entries(
  HARTHMERE_NATIVE_ITEM_ID_MANIFEST
)) {
  if (
    !HARTHMERE_BUSINESS_FURNITURE_ITEM_ID_BY_NATIVE_ID.has(nativeId) ||
    itemId === "muckwad"
  ) {
    HARTHMERE_BUSINESS_FURNITURE_ITEM_ID_BY_NATIVE_ID.set(nativeId, itemId);
  }
}

export function harthmereBusinessFurnitureAsset(
  itemId: string | number | undefined
): HarthmereBusinessFurnitureAsset | undefined {
  if (itemId === undefined || itemId === null) return undefined;
  const raw = String(itemId).trim();
  if (!raw) return undefined;
  const normalized = raw.replace(/^b:/, "");
  const direct =
    HARTHMERE_BUSINESS_FURNITURE_ASSETS[
      normalized as keyof typeof HARTHMERE_BUSINESS_FURNITURE_ASSETS
  ];
  if (direct) return direct;
  if (!/^[0-9]+$/.test(normalized)) return undefined;
  const semanticItemId =
    HARTHMERE_BUSINESS_FURNITURE_ITEM_ID_BY_NATIVE_ID.get(Number(normalized));
  return semanticItemId
    ? HARTHMERE_BUSINESS_FURNITURE_ASSETS[
        semanticItemId as keyof typeof HARTHMERE_BUSINESS_FURNITURE_ASSETS
      ]
    : undefined;
}
